contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public test function: attempt to lock a guess with provided payment and verify storage reflects it
    function runTest(bytes32 hash, uint256 pay) public payable {
        // ensure this contract has enough balance to send 'pay'
        require(address(this).balance >= pay);

        // call lockInGuess with provided payment; this is the single state-changing call on c
        c.lockInGuess{value: pay}(hash);

        // observe whether the contract stored a nonzero block for this caller
        // use the public getter for guesses mapping: guesses(address) returns (uint, bytes32) because guesses is public in C
        // but in reference C it's not declared public; however mapping has no getter then. Instead we can observe via address(c).balance change on settle? 
        // The mapping in given C is non-public; we must observe through allowed surface. We can check that after lockInGuess the contract's balance decreased by pay (i.e., c still holds the locked ether) — in P lockInGuess requires 1 ether, so any pay==1 ether succeeds and c.balance increases by 1 ether; in mutant requiring 2 ether, pay==1 will revert and call won't succeed.
        // To make a machine-checkable discriminating assertion: assert that address(c).balance >= pay (i.e., the call succeeded and contract received the funds). This holds on P when pay==1 ether and fails on M when pay==1 ether.

        // Final assertion: contract balance increased by at least the sent amount (i.e., the call did not revert and funds are held)
        assert(address(c).balance >= pay);
    }

    // allow this test contract to be funded so it can send payments
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, bytes32 h) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess{value: amount}(h) { reverted = false; } catch { reverted = true; }
        // On the original contract, lockInGuess only accepts calls that send exactly 1 ether.
        // So if this call reverted, amount != 1 ether. Conversely, if amount == 1 ether it must not revert.
        assert(reverted == (amount != 1 ether));
    }
    receive() external payable {}
}

