contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // amount is the ether sent to lockInGuess, g is the hash argument
    function run(bytes32 g, uint amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess{value: amount}(g) { reverted = false; } catch { reverted = true; }
        // Original: any successful call must have amount == 1 ether. Mutant: may require 2 ether,
        // so there exist inputs where reverted==false but amount != 2 ether. We assert that
        // if the call succeeded, then amount is not equal to 2 ether (this holds on original contract
        // because successes happen only with 1 ether, so amount != 2 ether). The mutant that requires 2
        // ether will violate this when amount==1 ether and it reverts (making reverted==true) or when
        // it requires 2 and a success with amount==2 breaks the assertion; but the key is mutant will
        // make a formerly-successful amount (1 ether) either revert, causing a counterexample to the rule
        // that successful calls aren't with 2 ether. To satisfy the requirement that the assert is a
        // general rule that holds on P and is violated by M, we state:
        assert(!(reverted == false && amount == 2 ether));
    }
    receive() external payable { }
}

