pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: an address that will act as the player
    function testFuzz_property(address player) public {
        vm.assume(player != address(0));
        // Give player enough ETH
        vm.deal(player, 5 ether);

        // First call: player locks in a guess paying exactly 1 ether
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(bytes32(uint256(1)));

        // read the stored block after first lock
        uint256 firstBlock = uint256(vm.load(address(c), keccak256(abi.encodePacked(player, uint256(0)))));
        // Note: We cannot directly access mapping storage layout via getter; instead observe via behavior:
        // call settle too early should revert because block.number is not > stored block

        // Ensure block recorded is non-zero by attempting to settle immediately,
        // which should revert (i.e., settle requires block.number > stored block)
        bool ok1;
        try c.settle() {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        // At this point, reference C: settle will revert (ok1 == false) because stored block is in future (block.number < stored.block).
        // Mutant that allowed overwrite would still set a block for the first call, so ok1 is also false here for both.

        // Advance one block to be able to settle if guess matches; we only need to change block.number so second lock can be distinguished
        vm.roll(block.number + 2);

        // Now, call lockInGuess again from same player with a different hash and 1 ether.
        // In the correct contract this second call should revert because guesses[player].block != 0 (prevent overwrite).
        // In the mutant it will succeed and overwrite the stored guess/block.
        bool ok2;
        vm.prank(player);
        try c.lockInGuess{value: 1 ether}(bytes32(uint256(2))) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // The universal property we assert: the correct contract never allows a second lockInGuess by the same player while they have an active guess.
        // Therefore, for all admissible inputs the reference yields ok2 == false. The mutant will allow ok2 == true for some inputs (same player),
        // so the test will fail on the mutant.
        assertTrue(!ok2);
    }
}

